function App() {
  const [items, setItems] = useState(['Hello']);
  const [pending, setPending] = useState(false);
  const add = async () => {
    const text = 'Msg ' + (items.length + 1);
    setItems(prev => [...prev, text + ' (sending…)']); // optimistic
    setPending(true);
    await new Promise(r => setTimeout(r, 600));        // fake server
    setItems(prev => prev.map(m => m === text + ' (sending…)' ? text + ' ✓' : m)); // reconcile
    setPending(false);
  };
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={add} disabled={pending}>{pending ? 'Sending…' : 'Add message'}</button>
      <ul>{items.map((m, i) => <li key={i}>{m}</li>)}</ul>
    </div>
  );
}

