function LikeButton({ initial, save }) {
  const [likes, setLikes] = useState(initial);
  const [optimistic, addOptimistic] = useOptimistic(
    likes,
    (cur, delta) => cur + delta
  );
  const onLike = async () => {
    addOptimistic(1);            // show +1 immediately
    const next = await save();    // real server value
    setLikes(next);               // commit; optimistic reconciles
  };
  return (
    <button onClick={onLike}>♥ {optimistic}</button>
  );
}
